parameters.item/cr174_cellcolor:
@if(
  items('Apply_to_each')?['cr174_inexam'],
  '#47a3ff',
  if(
    greater(int(First(outputs('List_other_column_variable_rows_1')?['body/value'])?['cr174_waittime']), 15),
    '#f76d8b',
    if(
      and(
        not(empty(items('Apply_to_each')?['cr174_checkintime'])),
        not(empty(items('Apply_to_each')?['cr174_appointmentstatuslabel'])),
        equals(items('Apply_to_each')?['cr174_appointmentstatuslabel'], 'Checked In')
      ),
      '#fafc9a',
      if ( equals(items('Apply_to_each')?['cr174_appointmentstatuslabel'], 'Checked Out'),
        '#D3CECF',
        '#FFFFFF'
      )
    )
  )
)

