      empty(items('Apply_to_each')?['cr174_first_examline_starttime']),
      '0 mins',
      concat(
        string(
          div(
            sub(
               ticks(convertFromUtc(
                    utcNow(),
                    first(outputs('List_rows_time_zone')?['body/value'])?['standardname']
                     )),
              ticks(items('Apply_to_each')?['cr174_first_examline_starttime'])
            ),
            600000000
          )
        ),
        ' mins'
      )
    )
  ),
  if(
    equals(items('Apply_to_each')?['cr174_appointmentstatuslabel'], 'Checked In'),
    concat(
      if(
        greater(
          int(First(outputs('List_other_column_variable_rows_1')?['body/value'])?['cr174_waittime']),
          15
        ),
        'Waiting',
        'Waiting'
      ),
      decodeUriComponent('%0A%0A'),
      if(
        empty(First(outputs('List_other_column_variable_rows_1')?['body/value'])?['cr174_lastendtime']),
        '0 mins',
        concat(
          string(First(outputs('List_other_column_variable_rows_1')?['body/value'])?['cr174_waittime']),
          ' mins'
        )
      )
    ),
    if(
      equals(items('Apply_to_each')?['cr174_appointmentstatuslabel'], 'Checked Out'),
      concat(
        'Checked Out',
        if(
          empty(items('Apply_to_each')?['cr174_checkedouton_local']),
          '',
          concat(
            decodeUriComponent('%0A%0A%0A'),
            formatDateTime(
              items('Apply_to_each')?['cr174_checkedouton_local'],
              'hh:mm tt'
            )
          )
        )
      ),
      if(
        equals(items('Apply_to_each')?['cr174_appointmentstatuslabel'], 'Confirmed'),
        concat(
          'Confirmed',
          if(
            empty(items('Apply_to_each')?['cr174_arrivaltime_local']),
            '',
            concat(
              decodeUriComponent('%0A%0A%0A'),
              formatDateTime(
                items('Apply_to_each')?['cr174_arrivaltime_local'],
                'hh:mm tt'
              )
            )
          )
        ),
        ''
      )
    )
  )
)

parameters.item/cr174_modifiedon_local:
@if(
  or(
    empty(string(first(outputs('List_rows_UTC_Offset')?['body/value'])?['cr174_utc_offset_standard'])),
    empty(string(first(outputs('List_rows_UTC_Offset')?['body/value'])?['cr174_utc_offset_daylightsaving']))
  ),
  null,
  addHours(
    utcNow(),
    int(
      if(first(outputs('List_rows_UTC_Offset')?['body/value'])?['cr174_dst'],
        first(outputs('List_rows_UTC_Offset')?['body/value'])?['cr174_utc_offset_daylightsaving'],
        first(outputs('List_rows_UTC_Offset')?['body/value'])?['cr174_utc_offset_standard']
      )
    ),
    'yyyy-MM-dd hh:mm tt'
  )
)

