parameters.item/cr174_waittime:
@if(
  and(
    equals(items('Apply_to_each')?['cr174_appointmentstatuslabel'], 'Checked In'),
    not(
      empty(
        coalesce(
          items('Apply_to_each')?['cr174_last_examline_endtime'],
          items('Apply_to_each')?['cr174_checkintime'],
          items('Apply_to_each')?['mzk_starttime']
        )
      )
    )
  ),
  div(
    sub(
      ticks(
        convertFromUtc(
          utcNow(),
          first(outputs('List_rows_time_zone')?['body/value'])?['standardname']
        )
      ),
      ticks(
        coalesce(
          items('Apply_to_each')?['cr174_last_examline_endtime'],
          items('Apply_to_each')?['cr174_checkintime'],
          items('Apply_to_each')?['mzk_starttime']
        )
      )
    ),
    600000000
  ),
  0
)
